update known_safe_harbors set evidence_summary = 'Cytogenetic band 19q13.4, intron 1 of PPP1R12C. Robust expression in hESCs/iPSCs without compromising pluripotency, but risk of silencing in cardiomyocytes, endothelial cells, myeloid cells, and hepatocytes, and in Jurkat T cells. Disrupts expression of PPP1R12C, TNNI3, and PPP6R1 (dense gene region). Via secondary review, not verified against the primary article.', stability = 'Robust in hPSCs; silencing risk after differentiation into cardiomyocytes/endothelial/myeloid/hepatocyte lineages' where source_pmid = '41511364' and evidence_summary = 'Banda 19q13.4, intrão 1 do gene PPP1R12C. Expressão robusta em hESCs/iPSCs sem comprometer pluripotência, mas risco de silenciamento em cardiomiócitos, células endoteliais, mieloides e hepatócitos, e em células Jurkat T. Perturba expressão de PPP1R12C, TNNI3 e PPP6R1 (região génica densa). Via review, não verificado contra artigo primário.';
update public_safe_harbors_staging set evidence_summary = 'Cytogenetic band 19q13.4, intron 1 of PPP1R12C. Robust expression in hESCs/iPSCs without compromising pluripotency, but risk of silencing in cardiomyocytes, endothelial cells, myeloid cells, and hepatocytes, and in Jurkat T cells. Disrupts expression of PPP1R12C, TNNI3, and PPP6R1 (dense gene region). Via secondary review, not verified against the primary article.', stability = 'Robust in hPSCs; silencing risk after differentiation into cardiomyocytes/endothelial/myeloid/hepatocyte lineages' where source_pmid = '41511364' and evidence_summary = 'Banda 19q13.4, intrão 1 do gene PPP1R12C. Expressão robusta em hESCs/iPSCs sem comprometer pluripotência, mas risco de silenciamento em cardiomiócitos, células endoteliais, mieloides e hepatócitos, e em células Jurkat T. Perturba expressão de PPP1R12C, TNNI3 e PPP6R1 (região génica densa). Via review, não verificado contra artigo primário.';

update known_safe_harbors set evidence_summary = 'Cytogenetic band 3p25.3 (hROSA26), intron 2 of THUMPD3. Stable expression in hESCs across multiple differentiation lineages; no silencing reported; used in HEK293 and hTERT-RPE1. Via secondary review, not verified against the primary article.', stability = 'Stable across differentiation lineages; no silencing reported' where source_pmid = '41511364' and evidence_summary = 'Banda 3p25.3 (hROSA26), intrão 2 do gene THUMPD3. Expressão estável em hESCs ao longo de múltiplas linhagens de diferenciação; sem silenciamento reportado; usado em HEK293 e hTERT-RPE1. Via review, não verificado contra artigo primário.';
