update known_safe_harbors set evidence_summary = 'Cytogenetic band 22q12.2, intergenic region between DRG1 and EIF4ENIF1. Stable expression of several transgenes in hiPSCs without silencing; supports recombinase-mediated cassette exchange (RMCE). Via secondary review, not verified against the primary article.', stability = 'Stable in hiPSCs; no silencing reported' where source_pmid = '41511364' and evidence_summary = 'Banda 22q12.2, região intergénica entre DRG1 e EIF4ENIF1. Expressão estável de vários transgenes em hiPSCs sem silenciamento; permite troca de cassete mediada por recombinase (RMCE). Via review, não verificado contra artigo primário.';
update public_safe_harbors_staging set evidence_summary = 'Cytogenetic band 22q12.2, intergenic region between DRG1 and EIF4ENIF1. Stable expression of several transgenes in hiPSCs without silencing; supports recombinase-mediated cassette exchange (RMCE). Via secondary review, not verified against the primary article.', stability = 'Stable in hiPSCs; no silencing reported' where source_pmid = '41511364' and evidence_summary = 'Banda 22q12.2, região intergénica entre DRG1 e EIF4ENIF1. Expressão estável de vários transgenes em hiPSCs sem silenciamento; permite troca de cassete mediada por recombinase (RMCE). Via review, não verificado contra artigo primário.';

update known_safe_harbors set evidence_summary = 'Cytogenetic band 3p21.31. Low probability of transgene expression, with gradual decline observed -- weak performance compared to AAVS1/ROSA26/H11/CLYBL. Upregulates flanking genes CCR1 and CCR3. Increases susceptibility to West Nile virus infection (the CCR5-delta32 mutation confers HIV resistance but carries this cost). Via secondary review, not verified against the primary article.', stability = 'Gradual decline in expression -- weakest performer among the loci compared' where source_pmid = '41511364' and evidence_summary = 'Banda 3p21.31. Baixa probabilidade de expressão do transgene, com declínio gradual observado -- desempenho fraco comparado a AAVS1/ROSA26/H11/CLYBL. Sobre-regula genes flanqueadores CCR1 e CCR3. Aumenta suscetibilidade a infeção pelo vírus do Nilo Ocidental (a mutação CCR5-delta32 confere resistência a HIV mas tem este custo). Via review, não verificado contra artigo primário.';
update public_safe_harbors_staging set evidence_summary = 'Cytogenetic band 3p21.31. Low probability of transgene expression, with gradual decline observed -- weak performance compared to AAVS1/ROSA26/H11/CLYBL. Upregulates flanking genes CCR1 and CCR3. Increases susceptibility to West Nile virus infection (the CCR5-delta32 mutation confers HIV resistance but carries this cost). Via secondary review, not verified against the primary article.', stability = 'Gradual decline in expression -- weakest performer among the loci compared' where source_pmid = '41511364' and evidence_summary = 'Banda 3p21.31. Baixa probabilidade de expressão do transgene, com declínio gradual observado -- desempenho fraco comparado a AAVS1/ROSA26/H11/CLYBL. Sobre-regula genes flanqueadores CCR1 e CCR3. Aumenta suscetibilidade a infeção pelo vírus do Nilo Ocidental (a mutação CCR5-delta32 confere resistência a HIV mas tem este custo). Via review, não verificado contra artigo primário.';

update known_safe_harbors set evidence_summary = 'Cytogenetic band 13q32.1, intron 2 of the CLYBL gene itself. "Robust and superior" expression compared to AAVS1 in hiPSCs and neural stem cells. Minimal disruption of local gene expression (~50x reduction of CLYBL itself). No silencing reported; preserves pluripotency markers and differentiation capacity. Via secondary review, not verified against the primary article.', stability = 'No silencing reported; robust across differentiation' where source_pmid = '41511364' and evidence_summary = 'Banda 13q32.1, intrão 2 do próprio gene CLYBL. Expressão "robusta e superior" comparada a AAVS1 em hiPSCs e estaminais neurais. Disrupção mínima da expressão local (~50x redução do próprio CLYBL). Sem silenciamento reportado; preserva marcadores de pluripotência e capacidade de diferenciação. Via review, não verificado contra artigo primário.';
update public_safe_harbors_staging set evidence_summary = 'Cytogenetic band 13q32.1, intron 2 of the CLYBL gene itself. "Robust and superior" expression compared to AAVS1 in hiPSCs and neural stem cells. Minimal disruption of local gene expression (~50x reduction of CLYBL itself). No silencing reported; preserves pluripotency markers and differentiation capacity. Via secondary review, not verified against the primary article.', stability = 'No silencing reported; robust across differentiation' where source_pmid = '41511364' and evidence_summary = 'Banda 13q32.1, intrão 2 do próprio gene CLYBL. Expressão "robusta e superior" comparada a AAVS1 em hiPSCs e estaminais neurais. Disrupção mínima da expressão local (~50x redução do próprio CLYBL). Sem silenciamento reportado; preserva marcadores de pluripotência e capacidade de diferenciação. Via review, não verificado contra artigo primário.';

update known_safe_harbors set evidence_summary = 'Cytogenetic band 4q13.1, intergenic, identified via pseudo-sites of the mCreI homing endonuclease. Robust integration and stable transgene expression for >45 days in rhabdomyosarcoma cells. Supports functional genome editing (Cas9 expression, PAX3/FOXO1 deletion). Not yet evaluated in iPSCs. Via secondary review, not verified against the primary article.', stability = 'Stable >45 days in rhabdomyosarcoma cells; not yet tested in iPSCs' where source_pmid = '41511364' and evidence_summary = 'Banda 4q13.1, intergénico, identificado via pseudo-sítios da endonuclease de homing mCreI. Integração robusta e expressão estável do transgene por >45 dias em células de rabdomiossarcoma. Suporta edição genómica funcional (expressão de Cas9, deleção de PAX3/FOXO1). Não avaliado ainda em iPSCs. Via review, não verificado contra artigo primário.';
update public_safe_harbors_staging set evidence_summary = 'Cytogenetic band 4q13.1, intergenic, identified via pseudo-sites of the mCreI homing endonuclease. Robust integration and stable transgene expression for >45 days in rhabdomyosarcoma cells. Supports functional genome editing (Cas9 expression, PAX3/FOXO1 deletion). Not yet evaluated in iPSCs. Via secondary review, not verified against the primary article.', stability = 'Stable >45 days in rhabdomyosarcoma cells; not yet tested in iPSCs' where source_pmid = '41511364' and evidence_summary = 'Banda 4q13.1, intergénico, identificado via pseudo-sítios da endonuclease de homing mCreI. Integração robusta e expressão estável do transgene por >45 dias em células de rabdomiossarcoma. Suporta edição genómica funcional (expressão de Cas9, deleção de PAX3/FOXO1). Não avaliado ainda em iPSCs. Via review, não verificado contra artigo primário.';

update known_safe_harbors set evidence_summary = 'Cytogenetic band 1q31.3, intergenic, discovered via computational screening. Robust, sustained mRuby expression for >90 days in HEK293T and Jurkat; >20 days in primary T cells; >25 days in fibroblasts. Silencing reported in iPSC applications; effect on pluripotency not assessed. Via secondary review, not verified against the primary article.', stability = 'Stable >90 days in cell lines; silencing reported in iPSC applications' where source_pmid = '41511364' and evidence_summary = 'Banda 1q31.3, intergénico, descoberto por triagem computacional. Expressão robusta e sustentada de mRuby por >90 dias em HEK293T e Jurkat; >20 dias em células T primárias; >25 dias em fibroblastos. Silenciamento reportado em aplicações de iPSC; efeito na pluripotência não avaliado. Via review, não verificado contra artigo primário.';
