update known_safe_harbors set evidence_summary = 'Cytogenetic band 3p24.3, intergenic, computational discovery. Performance similar to Rogi1; outperforms AAVS1 and CCR5. "Minimal" effect on the global transcriptional profile in HEK293T and Jurkat. Downregulation of the JUN oncogene observed. Via secondary review, not verified against the primary article.', stability = 'Similar profile to Rogi1; minimal transcriptome disruption' where source_pmid = '41511364' and evidence_summary = 'Banda 3p24.3, intergénico, descoberta computacional. Desempenho semelhante ao Rogi1; supera AAVS1 e CCR5. Efeito "mínimo" no perfil transcricional global em HEK293T e Jurkat. Sub-regulação do oncogene JUN observada. Via review, não verificado contra artigo primário.';
