update known_safe_harbors set evidence_summary = 'Cytogenetic band 1p13.2, intergenic. Stable expression in hESCs and iPSCs, with constitutive and inducible promoters. Supports Bxb1-integrase-mediated cassette exchange. Expression maintained for >=15 passages through differentiation. Via secondary review, not verified against the primary article.', stability = 'Stable for >=15 passages through differentiation' where source_pmid = '41511364' and evidence_summary = 'Banda 1p13.2, intergénico. Expressão estável em hESCs e iPSCs, com promotores constitutivos e indutíveis. Suporta troca de cassete mediada por integrase Bxb1. Expressão mantida por >=15 passagens ao longo de diferenciação. Via review, não verificado contra artigo primário.';
