update known_safe_harbors set evidence_summary = 'Cytogenetic band 7q36.1, within the ZNF767P pseudogene. T-cell-specific discovery via ATAC-seq. Durable CAR expression over multiple weeks in CAR-CD19 T cells; preserves the native T-cell receptor; long-term leukemia control demonstrated in vivo. Via secondary review, not verified against the primary article.', stability = 'Durable over multiple weeks; long-term in vivo control demonstrated' where source_pmid = '41511364' and evidence_summary = 'Banda 7q36.1, dentro do pseudogene ZNF767P. Descoberta específica de células T via ATAC-seq. Expressão duradoura de CAR ao longo de múltiplas semanas em células T CAR-CD19; mantém o recetor de células T nativo; controlo de leucemia a longo prazo demonstrado in vivo. Via review, não verificado contra artigo primário.';
